INSERT IGNORE INTO questions (question_type, content, options, correct_answer, analysis, difficulty, tags) VALUES
('CAREFUL_READING', '<h4>The Future of Urban Transportation</h4><p>Cities around the world are reimagining their transportation systems in response to congestion, pollution, and climate change. The dominant model of the 20th century—private car ownership supported by extensive highway networks—is increasingly recognized as unsustainable in dense urban environments. Emerging alternatives include electric vehicles, shared mobility services, micromobility options like e-bikes and scooters, and autonomous vehicles.</p><p>The electrification of transportation is proceeding more rapidly than many analysts predicted. Battery costs have fallen by nearly 90% since 2010, making electric vehicles increasingly cost-competitive with internal combustion engines. Several countries and many cities have announced plans to phase out the sale of new fossil fuel vehicles by 2035 or earlier. However, the environmental benefits of electrification depend on the cleanliness of the electricity grid; vehicles charged with coal-generated electricity offer limited emissions reductions.</p><p>The most transformative changes in urban mobility may come not from new vehicle technologies but from new models of access. The shift from personally owned vehicles to mobility-as-a-service—where users access transportation on demand through shared fleets—could dramatically reduce the number of vehicles needed to serve a given population. Combined with investments in public transit, walking, and cycling infrastructure, these changes could reshape cities into places designed around people rather than automobiles.</p>',
 NULL, 'PASSAGE', '', 6, '仔细阅读,城市交通,电动化'),
('CAREFUL_READING', 'What 20th century transportation model does the passage identify as unsustainable?', '[{"label":"A","text":"Public transit systems"},{"label":"B","text":"Private car ownership with highway networks"},{"label":"C","text":"Bicycle commuting"},{"label":"D","text":"Railway transportation"}]', 'B', '第一段: "private car ownership supported by extensive highway networks."', 5, '仔细阅读,细节'),
('CAREFUL_READING', 'By how much have battery costs fallen since 2010?', '[{"label":"A","text":"About 30%"},{"label":"B","text":"About 50%"},{"label":"C","text":"About 90%"},{"label":"D","text":"About 100%"}]', 'C', '第二段: "Battery costs have fallen by nearly 90% since 2010."', 6, '仔细阅读,细节'),
('CAREFUL_READING', 'What factor determines the environmental benefits of electric vehicles?', '[{"label":"A","text":"The color of the vehicle"},{"label":"B","text":"The cleanliness of the electricity grid"},{"label":"C","text":"The manufacturer brand"},{"label":"D","text":"The vehicle top speed"}]', 'B', '第二段末句: "depend on the cleanliness of the electricity grid."', 6, '仔细阅读,细节'),
('CAREFUL_READING', 'What is "mobility-as-a-service"?', '[{"label":"A","text":"A type of electric vehicle"},{"label":"B","text":"On-demand transportation access through shared fleets"},{"label":"C","text":"A government transportation department"},{"label":"D","text":"A road construction company"}]', 'B', '第三段: "where users access transportation on demand through shared fleets."', 7, '仔细阅读,概念'),
('CAREFUL_READING', 'The passage ultimate vision for cities is:', '[{"label":"A","text":"More highways and parking lots"},{"label":"B","text":"Cities designed around people rather than automobiles"},{"label":"C","text":"Completely eliminating all forms of transportation"},{"label":"D","text":"Returning to horse-drawn carriages"}]', 'B', '末段: "cities designed around people rather than automobiles."', 6, '仔细阅读,主旨'),

-- P15-P20: 6 more passages
('CAREFUL_READING', '<h4>The Science of Habit Formation</h4><p>Habits—automatic behaviors triggered by environmental cues—govern a remarkable proportion of daily life. Research suggests that approximately 40-45% of everyday actions are performed not as conscious decisions but as habitual responses. Understanding how habits form, persist, and change has therefore become a central concern of behavioral science, with implications for health, productivity, and personal development.</p><p>The neurological basis of habit formation involves a three-part loop: a cue that triggers the behavior, the routine behavior itself, and a reward that reinforces the association. Over time, this loop becomes encoded in the basal ganglia, a brain region associated with automatic behaviors, freeing up the prefrontal cortex for more complex cognitive tasks. This automation is evolutionarily adaptive—it would be cognitively exhausting to deliberate over every daily action—but it also makes habits remarkably resistant to change.</p><p>Changing established habits requires more than willpower. Research suggests that the most effective approaches focus on modifying the environment to reduce exposure to undesirable cues, substituting new routines for old ones while keeping the same cue and reward, and implementing what psychologist call "implementation intentions"—specific plans about when, where, and how to perform a new behavior. Small, consistent changes sustained over time prove more effective than dramatic but unsustainable transformations.</p>',
 NULL, 'PASSAGE', '', 6, '仔细阅读,习惯形成,行为科学'),
('CAREFUL_READING', 'What percentage of daily actions are estimated to be habitual?', '[{"label":"A","text":"10-15%"},{"label":"B","text":"40-45%"},{"label":"C","text":"70-80%"},{"label":"D","text":"90-100%"}]', 'B', '第一段: "approximately 40-45% of everyday actions."', 6, '仔细阅读,细节'),
('CAREFUL_READING', 'The habit loop consists of:', '[{"label":"A","text":"Thought, action, reflection"},{"label":"B","text":"Cue, routine, reward"},{"label":"C","text":"Goal, plan, outcome"},{"label":"D","text":"Input, process, output"}]', 'B', '第二段: "a cue that triggers the behavior, the routine behavior itself, and a reward."', 5, '仔细阅读,概念'),
('CAREFUL_READING', 'Where in the brain are habits encoded?', '[{"label":"A","text":"The prefrontal cortex"},{"label":"B","text":"The basal ganglia"},{"label":"C","text":"The cerebellum"},{"label":"D","text":"The hippocampus"}]', 'B', '第二段: "encoded in the basal ganglia."', 6, '仔细阅读,细节'),
('CAREFUL_READING', 'What are "implementation intentions"?', '[{"label":"A","text":"Vague goals for the future"},{"label":"B","text":"Specific plans about when, where, and how to perform a new behavior"},{"label":"C","text":"A type of meditation"},{"label":"D","text":"Government regulations on behavior"}]', 'B', '第三段: "specific plans about when, where, and how to perform a new behavior."', 7, '仔细阅读,概念'),
('CAREFUL_READING', 'According to the passage, what approach to habit change works best?', '[{"label":"A","text":"Dramatic, immediate transformations"},{"label":"B","text":"Small, consistent changes sustained over time"},{"label":"C","text":"Relying entirely on willpower"},{"label":"D","text":"Changing all habits simultaneously"}]', 'B', '末段: "Small, consistent changes sustained over time prove more effective."', 6, '仔细阅读,主旨'),

-- Remaining 6 passages
('CAREFUL_READING', '<h4>Blockchain Beyond Cryptocurrency</h4><p>Blockchain technology, best known as the foundation of cryptocurrencies like Bitcoin, has potential applications that extend far beyond digital money. At its core, blockchain is a distributed ledger technology that enables secure, transparent, and tamper-resistant record-keeping without the need for a central authority. This capability has attracted interest from industries ranging from supply chain management to healthcare to voting systems.</p><p>In supply chains, blockchain can provide an immutable record of a product journey from source to consumer. This transparency is valuable for verifying claims about organic certification, fair trade practices, or ethical sourcing. Walmart has implemented blockchain-based tracking for leafy greens, reducing the time needed to trace the origin of a food item from days to seconds—a capability with significant implications for food safety during contamination outbreaks.</p><p>Despite the hype, blockchain faces substantial barriers to widespread adoption. The technology remains complex and expensive to implement at scale. The energy consumption of some blockchain systems, particularly those using "proof of work" consensus mechanisms, raises environmental concerns. Most fundamentally, many of the problems blockchain promises to solve could be addressed more simply with conventional databases and institutional reforms. The challenge is to identify the specific use cases where decentralized trust genuinely adds value rather than represents a solution in search of a problem.</p>',
 NULL, 'PASSAGE', '', 7, '仔细阅读,区块链,科技'),
('CAREFUL_READING', 'According to the passage, blockchain core feature is:', '[{"label":"A","text":"Creating digital money"},{"label":"B","text":"Secure, transparent record-keeping without a central authority"},{"label":"C","text":"Increasing internet speed"},{"label":"D","text":"Replacing all databases"}]', 'B', '第一段: "distributed ledger technology that enables secure, transparent, and tamper-resistant record-keeping."', 6, '仔细阅读,概念'),
('CAREFUL_READING', 'How did Walmart apply blockchain?', '[{"label":"A","text":"To create a new cryptocurrency"},{"label":"B","text":"To track leafy greens from source to store"},{"label":"C","text":"To replace all cash registers"},{"label":"D","text":"To manage employee payroll"}]', 'B', '第二段: "implemented blockchain-based tracking for leafy greens."', 6, '仔细阅读,细节'),
('CAREFUL_READING', 'What is a major barrier to blockchain adoption?', '[{"label":"A","text":"It is too simple to implement"},{"label":"B","text":"It remains complex and expensive at scale"},{"label":"C","text":"It has been banned worldwide"},{"label":"D","text":"It only works for cryptocurrencies"}]', 'B', '第三段: "remains complex and expensive to implement at scale."', 6, '仔细阅读,细节'),
('CAREFUL_READING', 'What concern is raised about "proof of work" blockchain systems?', '[{"label":"A","text":"They are too secure"},{"label":"B","text":"They consume excessive energy"},{"label":"C","text":"They are too fast"},{"label":"D","text":"They are too transparent"}]', 'B', '第三段: "energy consumption...raises environmental concerns."', 6, '仔细阅读,细节'),
('CAREFUL_READING', 'The author suggests that blockchain should be applied:', '[{"label":"A","text":"To every problem regardless of fit"},{"label":"B","text":"Only to cryptocurrency"},{"label":"C","text":"To specific use cases where decentralized trust adds genuine value"},{"label":"D","text":"Nowhere—it has no value"}]', 'C', '末段: "identify the specific use cases where decentralized trust genuinely adds value."', 7, '仔细阅读,作者态度'),

-- P17-Final: Batch 4 more
('CAREFUL_READING', '<h4>The Anthropology of Gift-Giving</h4><p>Gift-giving, a practice universal across human cultures, serves functions far beyond the simple transfer of goods. Anthropologists have long recognized that gifts create, maintain, and sometimes sever social relationships. The French anthropologist Marcel Mauss, in his seminal 1925 essay "The Gift," argued that gift exchange is a "total social phenomenon" that simultaneously encompasses economic, legal, moral, religious, and aesthetic dimensions.</p><p>The obligation to reciprocate is central to gift economies. Unlike market transactions, which are typically completed at the moment of exchange, gifts create ongoing relationships of mutual obligation. The timing and magnitude of reciprocation communicate subtle messages about the state of the relationship. To return a gift of exactly equal value immediately, for example, can be interpreted as a rejection of the relationship rather than politeness. The delay between gift and counter-gift, and the acceptable range of equivalence, varies significantly across cultures.</p><p>In contemporary consumer societies, gift-giving has become deeply commercialized, with entire industries built around holidays like Christmas, Valentine Day, and Mother Day. Critics argue that commercialization has stripped gift exchange of its deeper social meanings. Yet even in highly commercialized contexts, gifts retain their power to express love, gratitude, obligation, and apology in ways that money alone cannot. The challenge for the giver is to select a gift that demonstrates knowledge of the recipient—what anthropologists call "successful symbolic labor"—without falling into the impersonal trap of purely monetary exchange.</p>',
 NULL, 'PASSAGE', '', 7, '仔细阅读,礼物,人类学'),
('CAREFUL_READING', 'What did Marcel Mauss argue about gift exchange?', '[{"label":"A","text":"It is purely economic"},{"label":"B","text":"It is a total social phenomenon encompassing multiple dimensions"},{"label":"C","text":"It is unique to Western cultures"},{"label":"D","text":"It should be replaced by monetary transactions"}]', 'B', '第一段: "a total social phenomenon that simultaneously encompasses economic, legal, moral, religious, and aesthetic dimensions."', 7, '仔细阅读,细节'),
('CAREFUL_READING', 'According to the passage, immediately returning a gift of equal value may signal:', '[{"label":"A","text":"Great politeness"},{"label":"B","text":"Rejection of the relationship"},{"label":"C","text":"Financial generosity"},{"label":"D","text":"Cultural sophistication"}]', 'B', '第二段: "can be interpreted as a rejection of the relationship rather than politeness."', 7, '仔细阅读,推理'),
('CAREFUL_READING', 'What is "successful symbolic labor" in gift-giving?', '[{"label":"A","text":"Spending a lot of money"},{"label":"B","text":"Selecting a gift that shows knowledge of the recipient"},{"label":"C","text":"Making the gift by hand"},{"label":"D","text":"Giving money instead of gifts"}]', 'B', '末段: "select a gift that demonstrates knowledge of the recipient."', 6, '仔细阅读,概念'),
('CAREFUL_READING', 'How does gift exchange differ from market transactions?', '[{"label":"A","text":"Gifts are always more valuable"},{"label":"B","text":"Gifts create ongoing relationships of mutual obligation"},{"label":"C","text":"Gifts involve no social meaning"},{"label":"D","text":"Gifts are only exchanged between strangers"}]', 'B', '第二段: "Unlike market transactions...gifts create ongoing relationships of mutual obligation."', 6, '仔细阅读,对比'),
('CAREFUL_READING', 'The author attitude toward the commercialization of gift-giving is:', '[{"label":"A","text":"It has completely destroyed the meaning of gifts"},{"label":"B","text":"Gifts retain social meaning even in commercialized contexts"},{"label":"C","text":"Commercialization has improved gift-giving"},{"label":"D","text":"Commercialization is irrelevant to gift-giving"}]', 'B', '末段: "even in highly commercialized contexts, gifts retain their power to express love, gratitude, obligation, and apology."', 7, '仔细阅读,作者态度');

INSERT IGNORE INTO questions (question_type, content, options, correct_answer, analysis, difficulty, tags) VALUES
('CAREFUL_READING', '<h4>Deepfakes and Democracy</h4><p>Deepfake technology, which uses artificial intelligence to create convincingly realistic but fabricated video and audio content, poses a novel threat to democratic processes. While manipulated media is not new—photographs have been altered since the invention of the camera—deepfakes lower the barrier to creating high-quality forgeries that are difficult even for experts to detect. A sufficiently sophisticated deepfake could show a political candidate saying or doing things they never said or did, potentially influencing election outcomes.</p><p>The challenge is compounded by the speed at which content spreads on social media. Research has consistently shown that false information travels faster and reaches more people than true information, partly because falsehoods tend to be more novel and emotionally arousing. By the time a deepfake is identified and debunked, it may have already been viewed by millions and shaped their perceptions irretrievably.</p><p>Responses to the deepfake threat span technical, legal, and educational domains. Detection tools using AI to identify artifacts invisible to the human eye are improving but remain in an arms race with the technology used to create deepfakes. Some jurisdictions have criminalized malicious deepfakes, though enforcement across borders remains difficult. Media literacy education, aimed at helping citizens critically evaluate the content they encounter, may be the most scalable long-term defense. Ultimately, the threat posed by deepfakes is not primarily technological but epistemic: it undermines the shared factual basis upon which democratic deliberation depends.</p>',
 NULL, 'PASSAGE', '', 7, '仔细阅读,深度伪造,民主'),
('CAREFUL_READING', 'What makes deepfakes more threatening than traditional photo manipulation?', '[{"label":"A","text":"They are easier to detect"},{"label":"B","text":"They lower the barrier to creating high-quality forgeries"},{"label":"C","text":"They are less convincing"},{"label":"D","text":"They spread more slowly"}]', 'B', '第一段: "deepfakes lower the barrier to creating high-quality forgeries."', 6, '仔细阅读,细节'),
('CAREFUL_READING', 'Why does false information spread faster than true information?', '[{"label":"A","text":"It is usually shorter"},{"label":"B","text":"It tends to be more novel and emotionally arousing"},{"label":"C","text":"It is always accompanied by images"},{"label":"D","text":"Social media algorithms block true information"}]', 'B', '第二段: "falsehoods tend to be more novel and emotionally arousing."', 7, '仔细阅读,推理'),
('CAREFUL_READING', 'What does the passage identify as the most scalable defense against deepfakes?', '[{"label":"A","text":"Government censorship"},{"label":"B","text":"Media literacy education"},{"label":"C","text":"Banning all AI technology"},{"label":"D","text":"Requiring all videos to be authenticated"}]', 'B', '第三段: "Media literacy education...may be the most scalable long-term defense."', 7, '仔细阅读,细节'),
('CAREFUL_READING', 'The author argues the fundamental threat of deepfakes is:', '[{"label":"A","text":"Economic damage to media companies"},{"label":"B","text":"They undermine the shared factual basis needed for democratic deliberation"},{"label":"C","text":"They make politicians look better than they are"},{"label":"D","text":"They increase social media engagement"}]', 'B', '末段: "undermines the shared factual basis upon which democratic deliberation depends."', 8, '仔细阅读,主旨'),
('CAREFUL_READING', 'What is the status of deepfake detection tools?', '[{"label":"A","text":"They can detect all deepfakes perfectly"},{"label":"B","text":"They are in an arms race with deepfake creation technology"},{"label":"C","text":"They have been abandoned"},{"label":"D","text":"They are only available to governments"}]', 'B', '第三段: "remain in an arms race with the technology used to create deepfakes."', 7, '仔细阅读,细节'),

-- P19-20: Final 2
('CAREFUL_READING', '<h4>The Economics of Vaccine Development</h4><p>The extraordinary speed with which COVID-19 vaccines were developed—less than a year from viral sequencing to emergency authorization—represented a triumph of modern biomedical science. However, this achievement was built on decades of prior investment in basic research, particularly in mRNA technology, and on unprecedented levels of government funding and advance purchase commitments that shifted the financial risk from pharmaceutical companies to taxpayers.</p><p>The vaccine development process reveals a deeper tension in pharmaceutical innovation. The diseases that receive the most research attention are those that affect wealthy populations—cancer, heart disease, and conditions prevalent in high-income countries—while diseases that primarily affect the poor in developing nations, such as malaria, tuberculosis, and neglected tropical diseases, receive comparatively little investment. This misalignment between health needs and research funding is not a market failure per se; it is the market working as designed, responding to effective demand rather than human need.</p><p>Proposed solutions include "push" mechanisms that fund research directly, "pull" mechanisms that guarantee markets for successful products, and prizes that reward innovation without creating monopolies. The challenge is to design incentive structures that leverage the power of pharmaceutical innovation while ensuring that the resulting products are accessible and affordable to those who need them most—a challenge that the pandemic brought into sharp relief but which predates COVID-19 by decades.</p>',
 NULL, 'PASSAGE', '', 7, '仔细阅读,疫苗,制药经济学'),
('CAREFUL_READING', 'What enabled the rapid development of COVID-19 vaccines?', '[{"label":"A","text":"Luck alone"},{"label":"B","text":"Decades of prior mRNA research plus massive government funding"},{"label":"C","text":"A single pharmaceutical company effort"},{"label":"D","text":"Reduced safety testing"}]', 'B', '第一段: "built on decades of prior investment...and unprecedented levels of government funding."', 6, '仔细阅读,细节'),
('CAREFUL_READING', 'According to the passage, pharmaceutical research priorities are driven by:', '[{"label":"A","text":"Global health needs"},{"label":"B","text":"Effective demand rather than human need"},{"label":"C","text":"United Nations directives"},{"label":"D","text":"Random selection"}]', 'B', '第二段: "responding to effective demand rather than human need."', 7, '仔细阅读,推理'),
('CAREFUL_READING', 'Which diseases does the passage identify as receiving less research investment?', '[{"label":"A","text":"Cancer and heart disease"},{"label":"B","text":"Conditions affecting wealthy populations"},{"label":"C","text":"Malaria, tuberculosis, and neglected tropical diseases"},{"label":"D","text":"All diseases equally"}]', 'C', '第二段: "malaria, tuberculosis, and neglected tropical diseases, receive comparatively little investment."', 6, '仔细阅读,细节'),
('CAREFUL_READING', 'What are "pull" mechanisms in the context of vaccine development?', '[{"label":"A","text":"Direct funding of research"},{"label":"B","text":"Guaranteed markets for successful products"},{"label":"C","text":"Publishing research results"},{"label":"D","text":"Training more scientists"}]', 'B', '第三段: "pull mechanisms that guarantee markets for successful products."', 7, '仔细阅读,概念'),
('CAREFUL_READING', 'The passage suggests the challenge of drug accessibility:', '[{"label":"A","text":"Was created by COVID-19"},{"label":"B","text":"Predated COVID-19 by decades"},{"label":"C","text":"No longer exists"},{"label":"D","text":"Only affects rich countries"}]', 'B', '末段: "predates COVID-19 by decades."', 7, '仔细阅读,细节');

INSERT IGNORE INTO questions (question_type, content, options, correct_answer, analysis, difficulty, tags) VALUES
('CAREFUL_READING', '<h4>Rewilding: Letting Nature Take Back Control</h4><p>Rewilding represents a paradigm shift in conservation biology. Rather than managing ecosystems intensively to maintain a particular state, rewilding aims to restore natural processes and then step back, allowing ecosystems to find their own equilibrium. This approach has gained momentum as traditional conservation methods have struggled to reverse biodiversity declines despite decades of effort and billions in expenditure.</p><p>The most famous example of rewilding is the reintroduction of gray wolves to Yellowstone National Park in 1995. The wolves, by preying on elk, reduced overgrazing along riverbanks, which allowed willow and aspen trees to regenerate. This in turn created habitat for beavers, whose dams created ponds that benefited fish, amphibians, and birds. The wolves triggered what ecologists call a "trophic cascade"—a chain of effects propagating down through the food web that ultimately reshaped the entire ecosystem.</p><p>Rewilding is not without controversy. Farmers worry about predation on livestock. Some conservationists argue that in a world of rapid climate change and habitat fragmentation, hands-off management is a luxury we cannot afford. Others question whether "wilderness" is a meaningful concept in the Anthropocene, an era defined by pervasive human influence. Despite these debates, rewilding has captured the public imagination and is being implemented at scales ranging from urban gardens to vast landscapes like the European Green Belt.</p>',
 NULL, 'PASSAGE', '', 7, '仔细阅读,再野生化,生态'),
('CAREFUL_READING', 'How does rewilding differ from traditional conservation?', '[{"label":"A","text":"It requires more intensive human management"},{"label":"B","text":"It restores natural processes and lets ecosystems find their own balance"},{"label":"C","text":"It focuses only on protecting individual species"},{"label":"D","text":"It ignores all ecological processes"}]', 'B', '第一段: "restore natural processes and then step back, allowing ecosystems to find their own equilibrium."', 7, '仔细阅读,概念'),
('CAREFUL_READING', 'What happened after wolves were reintroduced to Yellowstone?', '[{"label":"A","text":"All other animals disappeared"},{"label":"B","text":"A trophic cascade reshaped the entire ecosystem"},{"label":"C","text":"Nothing changed"},{"label":"D","text":"The wolves quickly died out"}]', 'B', '第二段: "a trophic cascade...that ultimately reshaped the entire ecosystem."', 6, '仔细阅读,细节'),
('CAREFUL_READING', 'What is a criticism of rewilding mentioned in the passage?', '[{"label":"A","text":"It is too cheap to implement"},{"label":"B","text":"Farmers worry about livestock predation"},{"label":"C","text":"It requires too many scientists"},{"label":"D","text":"It only works in tropical regions"}]', 'B', '第三段: "Farmers worry about predation on livestock."', 6, '仔细阅读,细节'),
('CAREFUL_READING', 'The concept of a "trophic cascade" refers to:', '[{"label":"A","text":"A waterfall in a national park"},{"label":"B","text":"Effects propagating through the food web from top predators"},{"label":"C","text":"The extinction of all species in an area"},{"label":"D","text":"A type of conservation funding"}]', 'B', '第二段: "a chain of effects propagating down through the food web."', 7, '仔细阅读,概念'),
('CAREFUL_READING', 'The passage overall tone toward rewilding is:', '[{"label":"A","text":"Dismissive"},{"label":"B","text":"Cautiously optimistic"},{"label":"C","text":"Hostile"},{"label":"D","text":"Indifferent"}]', 'B', '文章既展示了成功案例也承认争议，但指出rewilding已"captured the public imagination."', 7, '仔细阅读,态度');
